import React, { useState } from "react";
import StudentForm from "./components/StudentForm";
import StudentList from "./components/StudentList";
import StudentDetails from "./components/StudentDetails";
import "./styles.css";
import { FaDownload } from "react-icons/fa";

import {
  getStudents,
  addStudent as addStudentService,
  updateStudent as updateStudentService,
  deleteStudent as deleteStudentService,
} from "./services/studentService";

export default function App() {
  const [students, setStudents] = useState([]);
  const [selected, setSelected] = useState(null);
  const [editStudent, setEditStudent] = useState(null);

  const loadStudents = async () => {
    const data = await getStudents();
    setStudents(data);
  };

  const addStudent = async (s) => {
    const studentWithId = { ...s, id: Date.now() };
    const newStudent = await addStudentService(studentWithId);
    setStudents((prev) => [...prev, newStudent]);
  };

  const updateStudent = async (s) => {
    const updated = await updateStudentService(s.id, s);
    setStudents((prev) => prev.map(st => (st.id === s.id ? updated : st)));
    setEditStudent(null);
    if (selected?.id === s.id) setSelected(updated);
  };

  const deleteStudent = async (id) => {
  try {
    const response = await fetch(`http://localhost:5000/students/${id}`, {
      method: 'DELETE',
    });
    if (response.ok) {
      // Remove the student from local state to update UI
      setStudents(students.filter(student => student.id !== id));
      alert('Student deleted successfully');
    } else {
      alert('Failed to delete student');
    }
  } catch (error) {
    console.error('Error deleting student:', error);
  }
};


  return (
    <div className="app-container">
      <h1 className="title">Student Result Dashboard</h1>

      <div className="layout">
        <div className="left-panel">
          <div className="left-top card">
            {selected ? (
              <StudentDetails student={selected} />
            ) : (
              <div className="empty">Select a student to view details.</div>
            )}
          </div>

          <div className="left-bottom card">
            <h2 className="section-title">Add / Edit Student</h2>
            <StudentForm
              onAdd={addStudent}
              onUpdate={updateStudent}
              studentToEdit={editStudent}
            />
          </div>
        </div>

        <div className="right-panel card">
          <div className="panel-top">
            <button className="btn load-btn" onClick={loadStudents}>
              <FaDownload className="icon-sm" /> Load Students
            </button>
            <div className="spacer" />
            <div className="note">Right: Student list. Left: Details & form.</div>
          </div>
          <StudentList
            students={students}
            onSelect={(s) => { setSelected(s); }}
            onDelete={deleteStudent}
            onEdit={(s) => { setEditStudent(s); }}
          />
        </div>
      </div>
    </div>
  );
}
